import express from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { enqueueLedger } from "./events.js";

export const router = express.Router();
router.post("/webhooks/ledger", express.raw({ type: "application/json" }), async (req, res) => {
  const expected = createHmac("sha256", process.env.LEDGER_SECRET).update(req.body).digest();
  const received = Buffer.from(req.get("x-ledger-signature") || "", "hex");
  if (received.length !== expected.length || !timingSafeEqual(expected, received)) {
    return res.sendStatus(401);
  }
  await enqueueLedger(JSON.parse(req.body.toString("utf8")));
  return res.sendStatus(204);
});

