import { Webhooks } from '@octokit/webhooks';

export function connect(router, webhookSecret, accepted) {
  const webhooks = new Webhooks({ secret: webhookSecret });
  router.post('/github/webhook', async (req, res) => {
    const payload = req.body.toString('utf8');
    const signature = req.get('x-hub-signature-256');
    if (!signature || !(await webhooks.verify({ payload, signature }))) {
      return res.sendStatus(401);
    }
    accepted.push(JSON.parse(payload).ref);
    return res.sendStatus(204);
  });
}

import { Webhooks } from "@octokit/webhooks";
const hooks = new Webhooks({ secret: process.env.GITHUB_WEBHOOK_SECRET! });

export async function POST(req: Request) {
  const id = req.headers.get("x-github-delivery");
  const signature = req.headers.get("x-hub-signature-256");
  if (!id || !signature || req.headers.get("x-github-event") !== "push") {
    return new Response(null, { status: 400 });
  }
  await hooks.verifyAndReceive({
    id, name: "push", signature, payload: await req.text()
  });
  return new Response(null, { status: 202 });
}

export function deliveryBadge(stored: { headers: Record<string, string> }) {
