export function attachMembers(router, secret, members) {
  const webhook = new Webhook(secret);
  router.post('/webhooks/svix', express.text({ type: 'application/json' }), (req, res) => {
    const event = webhook.verify(req.body, req.headers);
    members.set(event.data.id, event.data.email);
    return res.sendStatus(204);
  });
}

import { Webhook as SignedDelivery } from "svix";

export async function POST(request: Request) {
  const signed = new SignedDelivery(process.env.IDENTITY_ENDPOINT_SECRET!);
  const headers = Object.fromEntries(request.headers.entries());
  const raw = await request.text();
  signed.verify(raw, headers);
  const event = JSON.parse(raw);
  return Response.json({ received: event.type });
}

export function addStatus(app, config) {
  app.get('/admin/svix/webhook/status', (_request, response) => {
    response.json({
      configured: Boolean(config.svixSecret),
      signatureHeader: 'svix-signature',
    });
  });
}

const repositoryEvents = new Map<number, string>();

export async function POST(request: Request) {
  const topic = request.headers.get("x-github-event");
  if (!topic) return new Response("Missing event", { status: 400 });
  const payload = await request.json();
  repositoryEvents.set(payload.repository.id, topic);
  return new Response(null, { status: 204 });
}

import { Webhooks } from "@octokit/webhooks";

const github = new Webhooks({ secret: process.env.GITHUB_WEBHOOK_SECRET! });
const sizes = new Map<string, number>();

export async function POST(request: Request) {
  const text = await request.text();
  const signature = request.headers.get("x-hub-signature-256");
  if (!signature || !await github.verify(text, signature)) {
    return new Response("Invalid signature", { status: 401 });
  }
  const data = JSON.parse(text);
  sizes.set(data.repository.full_name, data.repository.size);
  return new Response(null, { status: 204 });
}

import type { NextRequest } from "next/server";

const lastSeen = new Map<string, string>();

export async function POST(request: NextRequest) {
  const signature = request.headers.get("stripe-signature");
  if (!signature) return new Response("Missing signature", { status: 400 });
  const event = await request.json();
  lastSeen.set(event.type, event.id);
  return Response.json({ received: true });
}

import { Webhook } from "svix";

const webhook = new Webhook(process.env.SVIX_SIGNING_SECRET!);
const topics = new Set<string>();

export async function POST(req: Request) {
  const body = await req.text();
  try {
    const message = webhook.verify(body, {
      "svix-id": req.headers.get("svix-id") ?? "",
      "svix-timestamp": req.headers.get("svix-timestamp") ?? "",
      "svix-signature": req.headers.get("svix-signature") ?? ""
    }) as { type: string };
    topics.add(message.type);
    return new Response(null, { status: 204 });
  } catch {
    return new Response(null, { status: 400 });
  }
}

const receivedTypes = new Set<string>();

export async function POST(req: Request) {
  const delivery = req.headers.get("svix-id");
  const submittedAt = req.headers.get("svix-timestamp");
  if (!delivery || !submittedAt) return new Response(null, { status: 400 });
  const envelope = await req.json();
  receivedTypes.add(envelope.type);
  return Response.json({ accepted: delivery }, { status: 202 });
}

