import Stripe from "stripe";

const stripe = new Stripe(process.env.STRIPE_API_KEY!);
const totals = new Map<string, number>();

export async function POST(req: Request) {
  const signature = req.headers.get("stripe-signature");
  if (!signature) return new Response(null, { status: 400 });
  const raw = await req.text();
  try {
    const event = stripe.webhooks.constructEvent(raw, signature, process.env.STRIPE_WEBHOOK_SECRET!);
    totals.set(event.type, (totals.get(event.type) || 0) + 1);
    return new Response(null, { status: 204 });
  } catch {
    return new Response(null, { status: 400 });
  }
}

import { getSession } from "@/auth";
import { settings } from "@/settings";

export async function POST(req: Request) {
  const session = await getSession(req);
  if (!session) return new Response(null, { status: 401 });
  const { enabled } = await req.json();
  await settings.save(session.userId, { webhookNotifications: enabled === true });
  return new Response(null, { status: 204 });
}

import express from 'express';
