import { Router, json } from 'express';

const events = Router();
const repos = new Set();

events.post('/incoming/github/webhook', json(), (req, res) => {
  if (!req.get('x-hub-signature-256')) return res.sendStatus(400);
  repos.add(req.body.repository.full_name);
  return res.status(200).end();
});

